struct Data { int x; long y; };
Data array[10];

Data* d_ptr = array;
// Moves sizeof(Data) bytes (8 or 12)
d_ptr += 1;

char* byte_ptr = (char*)array;
// Moves exactly 1 byte
byte_ptr += 1;

// Pitfall: Interpreting byte-offset as Data*
// Points 1 byte into the first element (misaligned)
Data* bad_ptr = (Data*)(byte_ptr);

// Correct calculation of Nth byte offset
const int offset = 5;
Data* target = (Data*)((char*)array + offset * sizeof(Data));
